import {hazards,checkRoutes} from './core.js';
export function hideBasemapLabel(layer){return layer.type==='symbol'&&!/^(place_country|place_state|place_city_r)/.test(layer.id);}
export const project=([x,y])=>[-118.23+(x-400)*.00035,34.22-(y-220)*.00025];
export function overlayData(stage){return {hazards:{type:'FeatureCollection',features:hazards(stage).map(c=>({type:'Feature',properties:{},geometry:{type:'Polygon',coordinates:[Array.from({length:73},(_,i)=>project([c.x+Math.cos(i/72*Math.PI*2)*c.r,c.y+Math.sin(i/72*Math.PI*2)*c.r]))]}}))},routes:{type:'FeatureCollection',features:checkRoutes(stage).map(r=>({type:'Feature',properties:{id:r.id,blocked:r.blocked},geometry:{type:'LineString',coordinates:r.points.map(project)}}))}};}
let map,loaded=false,current={stage:0,layer:'all',selectedRoute:'B'};
export function updateMap(state){current=state;if(!loaded)return;const fc=f=>f?(f.type==='FeatureCollection'?f:{type:'FeatureCollection',features:[f]}):{type:'FeatureCollection',features:[]};if(map.getSource('pharos-fire'))map.getSource('pharos-fire').setData(state.fire||{type:'FeatureCollection',features:[]});if(map.getSource('pharos-evac'))map.getSource('pharos-evac').setData(fc(state.evacRoute));if(map.getSource('pharos-districts')){const sel=new Set(state.selectedAreas||[]);map.getSource('pharos-districts').setData({type:'FeatureCollection',features:(state.districts||[]).map(f=>({type:'Feature',properties:{GEOID:f.properties.GEOID,name:f.properties.name,kind:f.properties.kind,selected:sel.has(f.properties.GEOID)},geometry:f.geometry}))});}if(state.perimeters&&map.getSource('pharos-perimeters'))map.getSource('pharos-perimeters').setData(state.perimeters);}
export function zoomMap(delta){if(map)map.easeTo({zoom:map.getZoom()+delta,duration:300});}
export function frameRoute(coords){if(!map||!coords||!coords.length)return;const lons=coords.map(c=>c[0]),lats=coords.map(c=>c[1]);const bounds=[[Math.min(...lons),Math.min(...lats)],[Math.max(...lons),Math.max(...lats)]];try{const cam=map.cameraForBounds(bounds,{padding:{top:130,bottom:150,left:430,right:400}});if(!cam)throw 0;map.easeTo({center:cam.center,zoom:Math.min(cam.zoom,14),pitch:56,bearing:-15,duration:1500});}catch(e){map.easeTo({center:[(Math.min(...lons)+Math.max(...lons))/2,(Math.min(...lats)+Math.max(...lats))/2],zoom:12.6,pitch:56,bearing:-15,duration:1500});}}
export function initializeMap(onRoute,onDistrict){if(!globalThis.maplibregl)return;try{map=new maplibregl.Map({container:'maplibre-canvas',style:'https://basemaps.cartocdn.com/gl/dark-matter-gl-style/style.json',center:project([390,240]),zoom:13.3,pitch:55,bearing:-17,maxPitch:80,attributionControl:{compact:true},maxZoom:18,minZoom:9});map.on('style.load',()=>{for(const layer of map.getStyle().layers){if(hideBasemapLabel(layer))map.setLayoutProperty(layer.id,'visibility','none');}const d=overlayData(current.stage);for(const key of ['hazards','routes'])map.addSource('pharos-'+key,{type:'geojson',data:d[key]});map.addLayer({id:'hazard-fill',type:'fill',source:'pharos-hazards',paint:{'fill-color':'#eb835d','fill-opacity':.13,'fill-antialias':true}});map.addLayer({id:'hazard-core',type:'fill',source:'pharos-hazards',paint:{'fill-color':'#e56d49','fill-opacity':.035}});for(const [id,width,opacity,blur] of [['route-glow',11,.12,5],['route-line',3,.85,0]])map.addLayer({id,type:'line',source:'pharos-routes',layout:{'line-cap':'round','line-join':'round'},paint:{'line-color':['case',['get','blocked'],'#cf876b','#9bc9b8'],'line-width':width,'line-opacity':opacity,'line-blur':blur}});map.addSource('pharos-districts',{type:'geojson',data:{type:'FeatureCollection',features:[]}});map.addLayer({id:'district-fill',type:'fill',source:'pharos-districts',paint:{'fill-color':['case',['get','selected'],'#9bc9b8','#6f8ba0'],'fill-opacity':['case',['get','selected'],.3,.07]}});map.addLayer({id:'district-line',type:'line',source:'pharos-districts',paint:{'line-color':['case',['get','selected'],'#bfe3d4','#8094a6'],'line-width':['case',['get','selected'],2.2,.8],'line-opacity':.9}});map.addLayer({id:'district-label',type:'symbol',source:'pharos-districts',layout:{'text-field':['get','name'],'text-font':['Open Sans Regular'],'text-size':10,'text-letter-spacing':.06},paint:{'text-color':'#c3d2cc','text-halo-color':'#111718','text-halo-width':1.6}});map.addSource('pharos-perimeters',{type:'geojson',data:{type:'FeatureCollection',features:[]}});map.addLayer({id:'perimeter-fill',type:'fill',source:'pharos-perimeters',paint:{'fill-color':'#e4552e','fill-opacity':.22}});map.addLayer({id:'perimeter-line',type:'line',source:'pharos-perimeters',paint:{'line-color':'#ff7847','line-width':1.6,'line-dasharray':[2,1.5]}});map.addSource('pharos-points',{type:'geojson',data:{type:'FeatureCollection',features:[['OBSERVATION / 07',[450,215],'#f3946c'],['REVIEW ORIGIN',[350,270],'#b6ccc5'],['NORTH ASSEMBLY',[650,150],'#8baba0'],['SOUTH ASSEMBLY',[620,345],'#8baba0']].map(([label,p,color])=>({type:'Feature',properties:{label,color},geometry:{type:'Point',coordinates:project(p)}}))}});map.addLayer({id:'incident-points',type:'circle',source:'pharos-points',paint:{'circle-radius':4,'circle-color':['get','color'],'circle-stroke-width':4,'circle-stroke-color':'rgba(20,26,27,.7)'}});map.addLayer({id:'incident-labels',type:'symbol',source:'pharos-points',layout:{'text-field':['get','label'],'text-font':['Open Sans Regular'],'text-size':10,'text-offset':[0,1.5],'text-anchor':'top','text-letter-spacing':.12},paint:{'text-color':'#a3b4af','text-halo-color':'#111718','text-halo-width':2}});try{map.addSource('terrain-dem',{type:'raster-dem',tiles:['https://s3.amazonaws.com/elevation-tiles-prod/terrarium/{z}/{x}/{y}.png'],encoding:'terrarium',tileSize:256,maxzoom:14});map.setTerrain({source:'terrain-dem',exaggeration:1.4});}catch(e){}try{map.setSky({'sky-color':'#0a131b','horizon-color':'#223440','fog-color':'#0d1113','sky-horizon-blend':.6,'horizon-fog-blend':.55,'fog-ground-blend':.4,'atmosphere-blend':['interpolate',['linear'],['zoom'],8,.7,13,.25]});}catch(e){}try{const vs=Object.keys(map.getStyle().sources).find(id=>map.getStyle().sources[id].type==='vector');if(vs)map.addLayer({id:'buildings-3d',type:'fill-extrusion',source:vs,'source-layer':'building',minzoom:13,paint:{'fill-extrusion-color':['interpolate',['linear'],['coalesce',['get','render_height'],['get','height'],8],0,'#19242e',60,'#28333d',220,'#39505f'],'fill-extrusion-height':['interpolate',['linear'],['zoom'],13,0,15,['coalesce',['get','render_height'],['get','height'],8]],'fill-extrusion-base':['coalesce',['get','render_min_height'],0],'fill-extrusion-opacity':.85}});}catch(e){}map.addSource('pharos-fire',{type:'geojson',data:{type:'FeatureCollection',features:[]}});map.addLayer({id:'fire-extrusion',type:'fill-extrusion',source:'pharos-fire',paint:{'fill-extrusion-color':['interpolate',['linear'],['get','heat'],1,'#ffd27a',3,'#ff8a3c',6,'#e4381f',10,'#9e1a0f'],'fill-extrusion-height':['*',['get','heat'],30],'fill-extrusion-base':0,'fill-extrusion-opacity':.8}});map.addSource('pharos-evac',{type:'geojson',data:{type:'FeatureCollection',features:[]}});map.addLayer({id:'evac-glow',type:'line',source:'pharos-evac',layout:{'line-cap':'round','line-join':'round'},paint:{'line-color':'#8fd0ff','line-width':14,'line-opacity':.16,'line-blur':6}});map.addLayer({id:'evac-line',type:'line',source:'pharos-evac',layout:{'line-cap':'round','line-join':'round'},paint:{'line-color':'#cdeaff','line-width':4.5,'line-opacity':.96}});try{for(const id of ['route-line','route-glow','hazard-fill','hazard-core'])map.setLayoutProperty(id,'visibility','none');}catch(e){}loaded=true;document.body.classList.remove('map-unavailable');document.body.classList.add('map-ready');updateMap(current);});map.on('click','route-line',e=>onRoute(e.features[0].properties.id));map.on('click','district-fill',e=>{if(onDistrict)onDistrict(e.features[0].properties.GEOID);});map.on('mouseenter','district-fill',()=>map.getCanvas().style.cursor='pointer');map.on('mouseleave','district-fill',()=>map.getCanvas().style.cursor='');map.on('mouseenter','route-line',()=>map.getCanvas().style.cursor='pointer');map.on('mouseleave','route-line',()=>map.getCanvas().style.cursor='');map.on('mousemove',e=>{const target=document.querySelector('#coordinates');if(target)target.textContent=`${e.lngLat.lat.toFixed(4)}° N  ${Math.abs(e.lngLat.lng).toFixed(4)}° W`;});map.on('error',()=>{if(!loaded)document.body.classList.add('map-unavailable');});}catch{document.body.classList.add('map-unavailable');}}
